      "id": "hou-han-shu_ch-1_p-1",
      "chapterId": "hou-han-shu_ch-1",
      "order": 1,
      "canonicalText": "世祖光武皇帝諱秀，字文叔，南陽蔡陽人，高祖九世之孫也，出自景帝生長沙定王發。發生舂陵節侯買，買生鬱林太守外，外生鉅鹿都尉回，回生南頓令欽，欽生光武。光武年九歲而孤，養於叔父良。身長七尺三寸，美須眉，大口，隆準，日角。性勤於稼穡，而兄伯升好俠養士，常非笑光武事田業，比之高祖兄仲。王莽天鳳中，乃之長安，受尚書，略通大義。",
