      "canonicalText": "十一月，有星孛於張。光武遂將賓客還舂陵。時伯升已會眾起兵。初，諸家子弟恐懼，皆亡逃自匿，曰「伯升殺我」。及見光武絳衣大冠，皆驚曰「謹厚者亦復為之」，乃稍自安。伯升於是招新市、平林兵，與其帥王鳳、陳牧西擊長聚。光武初騎牛，殺新野尉乃得馬。進屠唐子鄉，又殺湖陽尉。軍中分財物不均，眾恚恨，欲反攻諸劉。光武斂宗人所得物，悉以與之，眾乃悅。進拔棘陽，與王莽前隊大夫甄阜、屬正樑丘賜戰於小長安，漢軍大敗，還保棘陽。",
