      "canonicalText": "王莽聞甄阜等死，大震懼，遣大司空王邑、大司徒王尋將兵百萬，其直道者四十二萬，西出洛陽，南向宛。五月，邑、尋發潁川，軍於昆陽。昆陽中漢軍才數千人，見莽兵盛，欲棄城走。光武曰：「今兵穀既少，而外寇彊大，並力禦之，功庶可立；如欲分散，勢無俱全。且宛城未拔，不能相救，昆陽即破，一日之間，諸部亦滅矣。今不同心膽共功名，反欲守妻子財物邪？」諸將皆憤，曰：「劉將軍何敢如是！」光武笑而起。",
