      "canonicalText": "六月己卯朔，光武自將精騎千餘為前鋒，去大軍四五里而陳。王尋、王邑亦遣兵數千合戰。光武奔之，斬首數十級。諸將喜曰：「劉將軍平生見小敵怯，今見大敵勇，甚可怪也，且復助戰。」光武復進，尋、邑兵不利，諸將各乘勝赴之，斬首千餘級。光武乃縱反間，宣言「宛下兵下」，莽軍聞之震恐。光武因選敢死三千人，從城西水上衝其中堅。尋、邑易之，自將萬餘人行陳，敕諸營皆按部毋得動。光武奔之，遂破其軍，尋敗走，光武窮追之，尋死亂兵中。城中兵亦鼓譟而出，中外合勢，震呼動天地。莽兵大潰，走者相騰踐，奔抪百餘裏間。會天大雷風，屋瓦皆飛，雨下如注，滎水暴溢，虎豹皆股戰，士卒溺死者以萬數，水為不流。王邑與輕騎千餘乘死人度水逃去。盡獲其軍實、輜重、車甲、珍寶，不可勝算，月餘日皆載之不盡，其餘燔燒之。",
