      "order": 11,
      "canonicalText": "光武至邯鄲，謁故趙繆王子林。林說光武決河水灌赤眉，光武不聽。林自以失言，恐，遂謀反。會卜者王郎自稱成皇帝子子輿，林等立之為天子，都邯鄲。乃發檄捕光武，懸賞同產侯。光武自薊南奔，晨夜進道，恐為邯鄲所及，遇驛吏，光武自稱「使者」，吏曰：「公是劉公。」光武大驚，馳去。",
