        "translation": "逃亡抵達饒陽縣時，隨行隨從官員全都飢腸轆轆疲憊不堪，光武帝只得自稱是邯鄲王郎朝廷派來的使者，走進驛站傳舍求食；驛站官吏正坐在桌前喫熱騰騰的飯菜，光武帝上前討要飯食，驛吏態度傲慢堅決不給。恰在此千鈞一發山窮水盡之際，上谷郡太守耿況、漁陽郡太守彭寵各自派遣自己的親生兒子耿弇、彭安率領數千名精銳幽州突騎鐵騎，主動南下歸順前來投奔光武帝！光武帝大喜過望，隨即率領這支強大的幽州鐵騎主力揮師向南回攻邯鄲！",
