      "order": 14,
      "canonicalText": "秋，光武擊銅馬賊於鄡，大破之。追至館陶，又破之。降者十餘萬人，封其渠帥為列侯。諸將未信，降者亦反側。光武令降渠帥各還營勒兵，自輕騎按行各營，降者大喜，曰：「蕭王推赤心置人腹中，安得不投死乎！」由是皆服。悉將其眾合為一軍，眾數十萬，故關西號光武為「銅馬帝」。",
