        "translation": "冬季十二月，赤眉軍攻入了函谷關。",
        "analysis": "【訓詁與名物】：「赤眉」新莽末年兩大農民起義軍之一，因士兵將眉毛塗紅作標誌而得名。「入關」指進入函谷關（或武關），即攻入長安所在的關中地區。\\n\\n【章法與結構】：四字紀事，極簡到了極致：時間（冬十二月）+ 主體與動作（赤眉入關）。\\n\\n【思想與義理】：這是一條改變天下大勢的戰略動態記錄。赤眉軍入關，意味著更始政權（劉玄）在長安的統治即將面臨毀滅性的打擊。這對遠在河北的劉秀來說，既是好消息，也是壞消息：好消息是更始政權將無暇顧及河北，劉秀可以安心發展自己的勢力；壞消息是天下即將陷入更加混亂的無主狀態，而赤眉軍這股龐大的力量，遲早會成為劉秀統一天下最危險的敵人。"
