      "id": "hou-han-shu_ch-1_p-17",
      "chapterId": "hou-han-shu_ch-1",
      "order": 17,
      "canonicalText": "二年春正月，光武追擊尤來、大槍、五幡於元氏，大破之。復逐北至順德，尤來等乘高逆戰，漢軍大奔，死者數千人。光武投下絕澗，宋子人馬武引光武出，乃得免。",
