        "analysis": "【訓詁與名物】：「五校」新莽末年活躍於河北一帶的農民起義軍番號。「安次」地名，在今河北廊坊一帶。「拔」攻克。「帥」統帥、首領。「復聚」重新聚集。「復」再次。\\n\\n【章法與結構】：本段記錄了劉秀對「五校」軍的兩次軍事打擊。前半部分寫第一次打擊（南擊、拔之、大破、斬帥），戰果輝煌；後半部分寫敵軍的死灰復燃（餘賊復聚）與劉秀的第二次打擊（復擊破之）。敘事簡潔，卻反映了平叛戰爭的反覆性。\\n\\n【思想與義理】：這段記載展示了河北地區農民起義軍強大的生命力以及劉秀平叛的艱難。「五校」軍在統帥被斬的情況下依然能夠「餘賊復聚」，說明當時社會矛盾極其尖銳，流民武裝具有極強的韌性。而劉秀對其進行的反覆軍事打擊（兩次「擊破」），則體現了他徹底肅清河北境內各種割據武裝的堅決意志，這是他建立穩定的大後方所必須付出的軍事代價。"
