      "order": 28,
      "canonicalText": "漢遭王莽，宗廟廢絕，豪傑憤怒，兆人塗炭。王與伯升首舉義兵，更始因其資以據帝位，而不能奉承大統，敗亂綱紀，盜賊日多，羣生危蹙。大王初征昆陽，王莽自潰；後拔邯鄲，北州弭定；參分天下而有其二，跨州據土，帶甲百萬。言武力則莫之敢抗，論文德則無所與辭。臣聞帝王不可以久曠，天命不可以謙拒，惟大王以社稷為計，萬姓為心。」光武又不聽。",
