      "readingAid": {
        "translation": "大漢江山不幸遭遇王莽篡位逆賊，劉氏宗廟廢絕無人祭祀，天下英雄豪傑憤怒起兵，億萬生靈百姓陷入塗炭絕境。大王當年同長兄劉伯升最早在南陽首舉反莽義兵，更始帝劉玄憑藉著大王兄弟開創的豐厚政治資本得以僥倖登上皇帝寶座；然而他卻平庸無能根本無法承擔天下大統重任，敗壞朝綱綱紀大亂，天下盜賊反而與日俱增，億萬蒼生生計陷入危殆窘迫之中！大王當年首戰征討昆陽，王莽百萬大軍自行崩潰瓦解；隨後揮師北伐攻拔邯鄲，北方各州郡全部徹底平定安寧；如今大王已坐擁天下三分之二的廣袤土地（參分天下而有其二），跨州連郡雄據沃野，麾下披甲精銳將士多達百萬雄師！論軍事武力則天下莫敢抵擋，論仁政文德則天下無人能出其右！微臣等聽聞天下天子帝位絕不可以長久空缺，至尊天命絕不可以一味謙遜推拒！唯求大王以江山社稷為根本大計，以萬民百姓為至上本心，早日登基即位皇帝尊號！光武帝依然謙遜堅決不肯聽從答應。",
        "analysis": "【篇旨與中山勸進表三分天下有其二帶甲百萬帝王不可久曠光武固辭】功臣集團第一次正式勸進綱領——痛斥王莽篡逆與更始昏聵，高度概括光武「昆陽破莽、邯鄲弭定、三分天下有其二、帶甲百萬、武莫敢抗文無所辭」之蓋世功德，光武謙遜固辭恪守古禮。\\n【詞義訓詁】「宗廟廢絕」：漢統中斷；「參分天下而有其二」：引《論語》周文王典故；「帶甲百萬」：東漢主力部隊總實力；「帝王不可久曠」：國家法統共主不可長久缺位。\\n【合法性建構】從血統、軍功、民心、版圖四重維度完整確立光武帝承接漢家正統的神聖合法性。"
      }
