      "id": "hou-han-shu_ch-1_p-29",
      "chapterId": "hou-han-shu_ch-1",
      "order": 29,
      "canonicalText": "行到南平棘，諸將復固請之。光武曰：「寇賊未平，四面受敵，何遽欲正號位乎？諸將且出。」耿純進曰：「天下士大夫捐親戚，棄土壤，從大王於矢石之閒者，其計固望其攀龍鱗，附鳳翼，以成其所志耳。今功業即定，天人亦應，而大王留時逆眾，不正號位，純恐士大夫望絕計窮，則有去歸之思，無為久自苦也。大眾一散，難可復合。時不可留，眾不可逆。」純言甚誠切，光武深感，曰：「吾將思之。」",
