      "readingAid": {
        "translation": "大軍行進抵達南平棘，諸位將領再次苦苦跪地懇求光武帝登基稱帝。光武帝推辭說：如今四方盜賊割據勢力尚未徹底平定，我軍四面受敵，為什麼偏偏如此急迫地想要確定天子名號帝位呢？各位將軍暫且退下吧。大將耿純毅然大步上前進諫說：天下全體士大夫與將士之所以拋棄親戚家族、拋棄故鄉鄉土田產，甘願冒著槍林彈雨在刀光劍影矢石之間誓死追隨大王浴血奮戰，大家內心的真實盤算，本來就是希望能藉機攀附龍鱗、依附鳳翼（攀龍鱗附鳳翼），以此來實現各自光宗耀祖封侯拜相的宏偉志向罷了！如今大王的蓋世功業已經基本底定，天象天意與人間民心全都相應契合；而大王如果一味拖延時機、違背全軍將士的強烈心願，遲遲不肯正式登基確定帝位名號，我耿純深深擔憂全軍士大夫將士將徹底心灰意冷希望破滅，大家將產生各奔東西回歸老家的離散之心，誰也不願再長久留在軍中為大王白白受苦了！全軍士氣一旦散去，日後將極難再次重新聚合！歷史天時機遇絕不可以長久停留延誤，全體三軍的共同民心意志絕不可以強行違背抗拒啊！耿純的這番肺腑之言極其真誠懇切直擊要害，光武帝深為震撼感動，沉思良久說道：我將認真深思考慮這件大事。",
        "analysis": "【篇旨與南平棘耿純進諫攀龍附鳳論時不可留眾不可逆政治利益同盟真諦】中國政治史與領導心理學上最深刻透徹之名諫——耿純以「士大夫拋家捨業從王矢石之間，固望攀龍鱗附鳳翼以成所志；大王不正號位士大夫望絕計窮有去歸之思；大眾一散難可復合」道破政治集團之利益本質，徹底打動光武帝下定登基決心！\\n【詞義訓詁】「攀龍鱗附鳳翼」：成語「攀龍附鳳」之典故出處，追隨聖主建功立業分享政權利益；「留時逆眾」：延誤歷史機遇、違背羣體訴求；「時不可留眾不可逆」：順應天時民意的最高政治法則。\\n【政治社會學考釋】耿純深刻揭示了封建政治同盟的本質——最高領袖必須及時將事業願景轉化為制度化的權力與產權封賞，給予追隨者明確的利益預期，才能維持政治集團的凝聚力與戰鬥力。"
      }
