      "id": "hou-han-shu_ch-1_p-30",
      "chapterId": "hou-han-shu_ch-1",
      "order": 30,
      "canonicalText": "行至鄗，光武先在長安時同舍生彊華自關中奉赤伏符，曰「劉秀發兵捕不道，四夷雲集龍鬥野，四七之際火為主」。群臣因復奏曰：「受命之符，人應為大，萬裏合信，不議同情，周之白魚，曷足比焉？今上無天子，海內淆亂，符瑞之應，昭然著聞，宜荅天神，以塞羣望。」光武於是命有司設壇場於鄗南千秋亭五成陌。",
