      "canonicalText": "六月己未，即皇帝位。燔燎告天，禋於六宗，望於羣神。其祝文曰：「皇天上帝，后土神祇，眷顧降命，屬秀黎元，為人父母，秀不敢當。羣下百辟，不謀同辭，鹹曰：『王莽篡位，秀發憤興兵，破王尋、王邑於昆陽，誅王郎、銅馬於河北，平定天下，海內蒙恩。上當天地之心，下為元元所歸。』讖記曰：『劉秀發兵捕不道，卯金修德為天子。』秀猶固辭，至於再，至於三。羣下僉曰：『皇天大命，不可稽留。』敢不敬承。」於是建元為建武，大赦天下，改鄗為高邑。",
