      "readingAid": {
        "translation": "更始三年（建武元年）夏六月己未日（公元25年8月5日），光武帝劉秀在鄗南千秋亭五成陌正式登基即位大漢皇帝！點燃柴火堆舉行莊嚴的燔燎儀式向皇天昭告即位（燔燎告天），以最高禋祀虔誠祭祀日月星辰司中司命等六宗神靈，遙祭四方名山大川羣神。光武帝親自宣讀的登基祭天祝文寫道：皇天至尊上帝，后土大地神祇，慈悲眷顧降下神聖天命，將天下億萬黎民蒼生託付給劉秀，命我為天下萬民之父母，劉秀自知德薄起初不敢承當。滿朝文武群臣與各路公卿諸侯，不謀而合異口同聲，齊聲上奏道：逆賊王莽篡奪大漢皇位，劉秀發憤起義興兵討伐，在昆陽戰場徹底擊破大司徒王尋、大司空王邑百萬莽軍，在黃河以北誅滅偽帝王郎、收降數十萬銅馬起義軍，逐步平定四海天下，海內萬民沐浴皇恩。上合天地神靈之心，下為億萬黎民所歸向。讖緯圖書上也明確記載著：劉秀發兵捕不道，卯金刀劉氏修明德行當為天子。劉秀依然謙遜堅決推辭，一而再、再而三地推讓。然而滿朝文武齊聲高呼：皇天所降之神聖大命，絕不可長久拖延遲滯！劉秀敢不敬畏恭敬承受皇天大命！光武帝於是正式宣佈建立年號為建武（改元建武），頒布大赦天下詔書，將登基聖地鄗縣改名為高邑！",
        "analysis": "【篇旨與六月己未光武登基即皇帝位燔燎告天建元建武改鄗為高邑東漢誕生】中華文明史上最偉大之開國大典——光武帝於公元25年六月己未在鄗南正式登基稱帝，燔燎告天、禋於六宗、宣讀祭天文告、建元「建武」、改鄗為高邑、大赦天下，延續大漢四百年國祚之東漢王朝正式誕生！\\n【詞義訓詁】「燔燎告天」：堆柴燃火將祭品升煙達於上天之最高祭天大典；「禋於六宗」：禋，音因，潔敬之祭，六宗指天地時寒暑日月星等自然神；「建武」：以武功定亂、以仁德建國之年號；「高邑」：尊崇登基聖地。\\n【世界歷史里程碑】東漢的建立不僅標誌著西漢滅亡後大一統中華帝國的成功重建，更開創了長達近兩百年的「光武中興」與「明章之治」盛世，是中華民族歷史上唯一一次由平民皇族成功復興大一統王朝的歷史奇蹟。"
      }
