      "readingAid": {
        "translation": "就在這個月，赤眉軍擁立了漢朝宗室劉盆子為天子。",
        "analysis": "【訓詁與名物】：「是月」指建武元年（公元25年）六月。「赤眉」赤眉軍。「劉盆子」漢高祖劉邦的孫子城陽景王劉章的後裔，當時只有十五歲，在赤眉軍中從事放牛的苦役。「天子」即皇帝。\\n\\n【章法與結構】：十一個字的極簡記錄，直接宣告了歷史上一個傀儡政權的誕生。時間（是月）+ 主體（赤眉）+ 動作與對象（立劉盆子為天子）。\\n\\n【思想與義理】：赤眉軍立劉盆子為帝，是古代農民起義中極具諷刺意味的一幕。赤眉軍本是反抗新莽暴政的底層流民武裝，但他們在攻入關中、即將推翻更始政權之時，為了讓自己的軍事行動擁有「正統」的法理外衣，竟然用抽籤（摸籌）的方式，從軍中找了一個放牛的皇族後裔（劉盆子）立為皇帝。這說明在西漢滅亡不久的社會心態中，「劉氏正統」依然具有強大的政治號召力。然而，這種缺乏政治綱領、純粹以流寇主義為主導的傀儡政權，註定無法長久，最終成為了光武帝劉秀統一天下的一塊墊腳石。"
      }
