        "analysis": "【訓詁與名物】：「宗室」指西漢皇族後裔。「劉茂」漢朝宗室成員，在天下大亂時起兵聚眾。「厭新將軍」他自己給自己封的稱號，意為「厭惡王莽新朝」。「降」投降、歸順。「中山王」諸侯王封號。\\n\\n【章法與結構】：本段記錄了一次地方武裝的歸降與政治封賞。前半句寫降者的身份與行動（宗室劉茂自號厭新將軍率眾降）；後半句寫劉秀的安撫與賞賜（封為中山王）。敘事簡明扼要。\\n\\n【思想與義理】：劉茂的「厭新將軍」稱號，生動地反映了當時天下人心思漢、反對王莽篡漢的社會共識。在羣雄逐鹿的亂世中，劉茂作為宗室，選擇率眾歸降剛剛稱帝的劉秀，說明劉秀在河北的軍事勝利與政治號召力已經開始產生強大的向心力。劉秀將投降的劉茂封為「中山王」（一個地位極高的同姓諸侯王），是一次極好的政治千金買骨，向天下展示了他對同宗兄弟的寬厚與優待，藉此吸引更多的地方勢力歸附大漢政權。"
