      "canonicalText": "己亥，幸懷。遣耿弇率彊弩將軍陳俊軍五社津，備滎陽以東。使吳漢率朱祐及廷尉岑彭、執金吾賈復、揚化將軍堅鐔等十一將軍圍朱鮪於洛陽。",
