      "readingAid": {
        "translation": "八月壬子日，光武帝（劉秀）祭祀了土神和穀神（社稷）。癸丑日，又在懷縣的行宮裡祭祀了漢高祖劉邦、漢太宗（文帝）、漢世宗（武帝）。隨後光武帝進軍巡幸河陽。更始政權的廩丘王田立前來投降。",
        "analysis": "【訓詁與名物】：「社稷」土神（社）與穀神（稷），代指國家政權。「高祖、太宗、世宗」西漢三位最重要的皇帝：劉邦、劉恆、劉徹。「懷宮」懷縣的行宮。「河陽」地名。「更始廩丘王」更始政權分封的諸侯王。\\n\\n【章法與結構】：本段記錄了光武帝在戰略進軍途中的一系列政治與軍事行動。前兩句是盛大的國家級祭祀（祭社稷、祠三祖）；後兩句則是行軍（幸河陽）與政治招降的成果（田立降）。將「神明祖先的庇佑」與「現實政敵的歸降」並列，強化了劉秀天命所歸的敘事。\\n\\n【思想與義理】：劉秀在「懷宮」祭祀社稷與西漢三位最偉大皇帝（高祖、太宗、世宗），是一場極具宣示意義的政治典禮。這不僅是在向上天和祖宗昭告自己已經繼承了大統，更是向天下人表明：他建立的政權不是一個新的朝代，而是西漢正統的直接延續。這種「中興」的法理建構，對當時心懷漢室的天下百姓與士大夫具有極強的號召力。緊接著廩丘王田立的投降，便成了這種政治號召力轉化為現實利益的直接證明。"
      }
