      "readingAid": {
        "translation": "九月，赤眉大軍攻克長安，更始帝劉玄棄城狼狽逃往高陵。辛未日，光武帝頒布深具仁德的恩撫詔書宣佈：更始帝兵敗破產，拋棄都城倉皇逃亡，其妻子家眷衣衫襤褸流落荒野道路之中。朕對此深感憐憫與痛心！如今朕正式冊封更始帝為淮陽王！全天下各地官吏百姓如果膽敢有圖謀謀害更始帝性命的，一律按大逆不道謀反重罪依法嚴懲！",
        "analysis": "【篇旨與赤眉攻陷長安更始奔高陵光武仁心詔封更始為淮陽王嚴禁加害】光武帝博大仁厚的至尊胸懷——在長兄被更始謀害的大仇之下，面對更始敗亡流離，光武不僅不落井下石，反而詔封其為淮陽王、嚴令全天下保護其生命安全，展現千古罕見的王者之風！\\n【詞義訓詁】「流冗」：流落漂泊無依；「罪同大逆」：以最高死刑罪名保護昔日政敵。\\n【政治格局與仁德】超越狹隘的個人私怨，以國家元首的大仁大義收拾人心，奠定東漢寬和仁厚的統治基調。"
      }
