      "readingAid": {
        "translation": "建武二年春正月甲子朔日，天空中出現了日食天象。大司馬吳漢率領九位將軍在鄴城以東向檀鄉起義軍發動總攻，大破敵軍並接受其投降。庚辰日，光武帝舉行盛大的大分封大典：將全體開國功臣全部冊封為列侯，其中立下蓋世大功的功臣封國最多享有四個縣的廣大封邑（大國四縣），其餘功臣依照功勞大小各自享受不同封邑。光武帝頒布警誡功臣戒驕戒躁詔書宣佈：人之常情在得到滿足富貴之後，最容易陷入肆意放縱的弊病，貪圖一時片刻的享樂慾望，而忘記了謹言慎行戒除刑罰的崇高道義。各位將軍創立的功業無比深遠博大，朕真心實意渴望大家的榮華富貴能夠世世代代傳承於無窮歲月！希望各位應當如同面臨萬丈深淵、如同腳踩薄冰一樣（如臨深淵如履薄冰），戰戰兢兢，一天比一天更加謙遜謹慎！朝中凡是立下顯赫戰功尚未得到封賞報償、名冊尚未呈報立案的將士，由大鴻臚官署火速加緊造冊呈報，朕將依照功勞等次全額補錄封賞！博士丁恭在朝堂上提出異議進諫說：古代聖明帝王分封諸侯封地從來不超過方圓百里，所以《易經》說利於建立諸侯取法於雷電震動，強幹弱枝才是國家長治久安的根本法度。如今陛下冊封諸侯列侯竟然多達四個縣，這完全不符合古代聖王的制度法制！光武帝駁斥回答說：自古以來各個國家的滅亡，全都是因為君主殘暴無道所致，朕還從來沒有聽說過因為賞賜給功臣的土地太多而導致國家滅亡的！光武帝隨即派遣謁者親赴各將軍軍營當面授予金印紫綬，在冊封策書中深情告誡道：身處尊貴高位而不驕傲自滿，地位才能長久高聳而不傾覆危殆（在上不驕高而不危）；恪守法度節制慾望，財富權位才能圓滿充盈而不外溢傾覆（滿而不溢）！各位務必敬畏法度深刻以此自戒！將這份無上榮耀傳承給你們的子子孫孫，世代長久作為我們大漢王朝的忠誠藩屏！",
        "analysis": "【篇旨與大封功臣皆為列侯大國四縣駁博士丁恭百里古制在上不驕如臨深淵戒敕功臣千古名篇】東漢開國產權制度與功臣管理哲學最高典範——大封列侯大國四縣，力駁博士丁恭教條主義百里古制（古之亡國皆以無道未嘗聞功臣地多而滅亡者），策書告誡「如臨深淵如履薄冰在上不驕高而不危滿而不溢」，奠定東漢功臣全員善終、不殺功臣之千古政治美談！\\n【詞義訓詁】「大國四縣」：突破西漢一縣一侯常規，給予頂級功臣鄧禹、吳漢等極豐厚封邑；「未嘗聞功臣地多而亡」：光武對功臣極致信任與政治豁達；「如臨深淵如履薄冰」：引《詩經》告誡富貴保全之道；「長為漢藩」：建立皇權與功臣世家的長期契約。\\n【政治文明與功臣保全】光武帝徹底打破了漢高祖殺戮功臣與宋太祖杯酒釋兵權的零和博弈，以極其優厚的物質保障、崇高的政治榮譽與嚴肅的道德約束，實現了君臣相保、功臣子孫與國同休的最高政治和諧。"
      }
