        "analysis": "【訓詁與名物】：「壬午」干支紀日。「鄧曄、於匡」更始帝劉玄手下的將領，曾在長安抵抗赤眉軍。「降」投降光武帝政權。「皆復爵位」指劉秀承認並恢復了他們在更始政權時的將軍稱號和爵位。\\n\\n【章法與結構】：這是一條關於招降納叛的簡明記錄。主語（鄧曄、於匡降）+ 皇帝的處置（皆復爵位）。\\n\\n【思想與義理】：隨著更始帝被殺，更始政權龐大的政治遺產與軍事力量成了各方爭奪的焦點。鄧曄、於匡作為更始舊將，在走投無路之際選擇歸降劉秀，這說明劉秀的政權已經成為天下正統的避風港。劉秀對他們「皆復爵位」的處理，展現了極高的政治手腕：他不僅沒有清算這些曾經的「政敵」，反而全盤接收了他們的政治待遇。這是一種極具示範效應的千金買骨，目的是為了安撫和吸引更多搖擺不定的更始舊部歸順東漢，從而在兵不血刃中迅速擴張實力。"
