        "translation": "三月乙未日，光武帝頒布大赦天下詔書，下發減輕刑罰重大司法詔令宣佈：近來全國各級監獄大牢中關押了許多遭受冤屈的無辜百姓，司法官吏斷案用刑過於殘酷深刻嚴苛，朕對此深感悲憫與痛惜！孔子曾經教導說：國家刑罰如果不能做到公平中正恰當，天下百姓就將手足無措無所適從（刑罰不中則民無所措手足）！特命令主管司法的朝廷中二千石官員、諸大夫、博士、議郎等文武百官共同商討研究，大幅刪減並減輕國家嚴刑峻法（議省刑法）！",
