        "analysis": "【訓詁與名物】：「廷尉」九卿之一，主管司法。「岑彭」東漢大將。「徵南大將軍」臨時設置的高級軍事統帥稱號。「鄧奉」在南陽叛亂的地方豪強。「堵鄉」地名，在南陽境內。\\n\\n【章法與結構】：本段記錄了漢軍平定南方叛亂的重大戰略部署。時間（冬十一月）+ 人事任命（以岑彭為徵南大將軍）+ 軍事行動（率八將軍討鄧奉於堵鄉）。\\n\\n【思想與義理】：鄧奉在南陽（劉秀的龍興之地）的叛亂，猶如一把匕首插在東漢政權的後腰上。為了徹底解決這個心腹大患，劉秀不惜血本，起用智勇雙全的岑彭為統帥，並調集了「八將軍」的龐大兵力進行圍剿。這反映了劉秀對南陽局勢的極度重視，以及對平定內部叛亂的堅決態度。在攘外（打赤眉、劉永）必先安內的戰略指導下，平定鄧奉成為了東漢軍隊此時的首要任務。"
