        "translation": "銅馬、青犢、尤來等起義軍的殘部，在上郡共同擁立孫登為天子。不久，孫登的部將樂玄便殺了孫登，帶領著五萬多部眾向東漢投降了。",
        "analysis": "【訓詁與名物】：「銅馬、青犢、尤來」皆為新莽末年北方著名的農民起義軍番號。「餘賊」殘餘部隊。「上郡」郡名，在今陝西榆林一帶。「孫登」被農民軍擁立的傀儡皇帝。「樂玄」孫登的部將。「降」投降漢朝。\\n\\n【章法與結構】：本段記錄了一場鬧劇般的稱帝與覆滅。前半句是草臺班子的搭建（餘賊共立孫登為天子）；後半句是迅速的內訌與崩潰（將殺登，以眾降）。兩相對比，極具戲劇性。\\n\\n【思想與義理】：孫登上郡稱帝，是秦末漢初流民武裝中典型的「立傀儡以號令眾人」的政治把戲。這些殘餘的農民軍（銅馬、青犢等）在被劉秀擊潰後，逃遁到邊疆地區，試圖通過擁立「天子」來重聚人心。然而，這種缺乏政治基礎和統馭能力的草根皇權極其脆弱，很快就死於內部的權力傾軋（樂玄殺登）。樂玄率五萬大軍投降，不僅讓這場稱帝鬧劇草草收場，也為劉秀的東漢政權憑空增加了一支龐大的生力軍，進一步削弱了北方的反對勢力。"
