      "order": 86,
      "canonicalText": "馮異與赤眉戰於崤底，大破之，餘眾南向宜陽，帝自將徵之。己亥，幸宜陽。甲辰，親勒六軍，大陳戎馬，大司馬吳漢精卒當前，中軍次之，驍騎、武衛分陳左右。赤眉望見震怖，遣使乞降。丙午，赤眉君臣面縛，奉高皇帝璽綬，詔以屬城門校尉。戊申，至自宜陽，己酉，詔曰：「羣盜縱橫，賊害元元，盆子竊尊號，亂惑天下。朕奮兵討擊，應時崩解，十餘萬眾束手降服，先帝璽綬歸之王府。斯皆祖宗之靈，士人之力，朕曷足以享斯哉！其擇吉日祠高廟，賜天下長子當為父後者爵，人一級。」",
