      "readingAid": {
        "translation": "割據睢陽的劉永冊立董憲為海西王，冊立張步為齊王。張步隨後殺害了光武帝派去安撫他的光祿大夫伏隆，並發動了叛亂。",
        "analysis": "【訓詁與名物】：「劉永」關東割據政權首領，自稱天子。「董憲、張步」關東地區擁兵自重的強大軍閥。「海西、齊」諸侯王國名。「光祿大夫伏隆」前文提到他成功招降了張步，被留在齊地安撫。「反」叛漢。\\n\\n【章法與結構】：本段記錄了東方戰局的急急惡化。前半部分是敵方（劉永）的政治拉攏與結盟（立董憲、張步為王）；後半部分則是這種拉攏導致的殘酷後果（張步殺伏隆而反）。敘事充滿了政治背叛的血腥氣。\\n\\n【思想與義理】：張步的叛漢殺使，暴露了亂世中軍閥毫無底線的投機本質。張步之前歸降劉秀，只是為了在夾縫中求生存的權宜之計；當劉永拋出「齊王」這樣極具誘惑力的政治籌碼時，他毫不猶豫地撕毀了與漢朝的協議，殺害了伏隆（這是一種徹底決裂的「投名狀」）。張步的反叛，使得山東半島再次成為抗漢的前沿陣地，讓劉秀在關東面臨著劉永、董憲、張步組成的強大軍事同盟。這是東漢平定東方過程中的一次重大外交與戰略挫折。"
      }
