        "analysis": "【訓詁與名物】：「幸」皇帝巡視。「懷」懷縣。「吳漢」東漢名將，雲臺二十八將之第二位，以作戰勇猛果敢著稱。「青犢」農民起義軍番號。「軹（zhǐ）」地名，在今河南濟源。「降之」招降。\\n\\n【章法與結構】：本段記錄了光武帝在懷縣前線指揮的一場掃蕩戰。先寫皇帝駐蹕之地（幸懷）；再寫主將與軍事行動（遣吳漢……擊青犢於軹西）；最後寫戰役結果（大破降之）。\\n\\n【思想與義理】：懷縣再次成為劉秀指揮作戰的戰略中樞。青犢軍是一支極為頑強的農民武裝，之前曾在上郡參與擁立傀儡皇帝（孫登），失敗後又流竄回中原。劉秀派最能打硬仗的吳漢去對付他們，在軹縣（靠近太行山的重要通道）取得了決定性的勝利。大破並招降青犢，進一步掃清了洛陽北部的殘餘軍事威脅，為漢軍能夠全力應對關東（劉永）與關中（赤眉）的兩線作戰提供了安全的大後方。"
