        "analysis": "【訓詁與名物】：「耿弇」東漢開國名將，雲臺二十八將之第四位，以善於指揮騎兵、攻堅克難著稱。「延岑」流竄的割據軍閥。「穰（ráng）」地名，在今河南鄧州，當時屬於南陽郡。「大破之」擊敗。\\n\\n【章法與結構】：十一字戰報。主將與敵手（耿弇與延岑）+ 地點（戰於穰）+ 結果（大破之）。\\n\\n【思想與義理】：延岑在關中被馮異擊敗（前文「戰於上林破之」）後，流竄到了南陽一帶的穰縣。劉秀派最善於長途奔襲和攻堅的耿弇去對付他。耿弇在穰縣的勝利，不僅再次重創了延岑的軍事力量，也徹底清除了這個流竄軍閥對劉秀大本營（南陽）的威脅，迫使延岑不得不繼續向南逃竄，最終投靠了蜀地的公孫述。"
