      "readingAid": {
        "translation": "虎牙大將軍蓋延攻克了睢陽城，俘獲並殺死了劉永。然而，劉永手下的將領蘇茂和周建卻擁立了劉永的兒子劉紆為新的梁王，繼續抵抗漢軍。",
        "analysis": "【訓詁與名物】：「蓋延拔睢陽」承接前文蓋延圍睢陽的軍事行動。「獲劉永」指抓獲劉永（據《後漢書·劉永傳》，劉永在逃跑途中被部將殺死，首級獻給漢軍）。「蘇茂、周建」原為更始政權將領，後投靠劉永的軍閥。「紆（yū）」劉永之子。「梁王」劉永家族世襲的封號。\\n\\n【章法與結構】：這是一段具有轉折意味的戰報。前半句是漢軍的巨大勝利與敵酋的覆滅（拔睢陽，獲劉永）；後半句用一個「而」字轉折，寫敵方陣營的死灰復燃（蘇茂等立永子紆為王）。\\n\\n【思想與義理】：睢陽的陷落與劉永的覆滅，標誌著關東地區最強大的割據政權在法理與軍事上的崩潰。但蘇茂等人擁立劉永之子劉紆為梁王，說明關東地區的豪強與軍閥並不甘心失敗。他們雖然失去了劉永這個強有力的核心，但依然試圖通過擁立一個傀儡（劉紆）來維持一個反漢的政治同盟，以保住自己的既得利益。這表明，消滅一個政權的首腦並不等於徹底平定該地區，劉秀在關東依然面臨著艱苦的殘匪肅清戰。"
      }
