        "translation": "在這一年裡，割據廬江的李憲自立為天子。佔據西北的西州大將軍隗囂向光武帝呈遞了奏章表示歸順。建義大將軍朱祐率領祭遵等人在東陽與延岑交戰，斬殺了延岑手下的將領張成。",
        "analysis": "【訓詁與名物】：「是歲」指建武三年。「李憲」盤踞在江淮（廬江）一帶的軍閥。「隗囂（wěi xiáo）」據守隴右的強大軍閥。「奉奏」呈遞奏章，表示名義上的臣服。「朱祐」雲臺二十八將之一。「延岑」流竄軍閥。「東陽」地名。「張成」延岑部將。\\n\\n【章法與結構】：本段將三個發生在不同地域、性質迥異的事件並列記錄。第一句是南方軍閥的政治野心（李憲稱帝）；第二句是西方軍閥的外交姿態（隗囂奉奏）；第三句是東方/南方戰場的具體軍事衝突（朱祐擊延岑）。\\n\\n【思想與義理】：這三個事件生動地勾勒出了建武三年天下局勢的複雜性。李憲在江淮稱帝，說明天下依然處於諸侯爭霸的最高潮，任何人只要稍微有了地盤就想過一把皇帝癮。而隗囂的「奉奏」則是一種政治投機，他在公孫述和劉秀之間搖擺不定，此時選擇向劉秀上奏，是為了在劉秀平定中原時保全自己的西北割據地位。至於朱祐在東陽擊敗延岑，則是東漢軍隊在第一線實打實地消滅流竄武裝的軍事行動。這三條記錄交織在一起，反映了劉秀統一天下過程中的政治博弈與軍事征伐。"
