        "analysis": "【訓詁與名物】：「右將軍」高級將軍稱號。「鄧禹」東漢開國名將，之前因回溪之敗被免去大司徒之職，此處以右將軍身份重新領兵。「延岑」流竄的割據軍閥。「武當」地名，在今湖北丹江口一帶。「破之」擊破。\\n\\n【章法與結構】：這是一條簡明的戰報。主帥與兵力（鄧禹率二將軍）+ 敵手與地點（與延岑戰於武當）+ 結果（破之）。\\n\\n【思想與義理】：鄧禹在經歷了關中大敗和被免去三公職務後，再次被劉秀啟用（任命為右將軍），這體現了劉秀對這位心腹大患的不離不棄與信任。鄧禹也不負眾望，在武當（靠近漢水流域）成功擊敗了老對手延岑。這場戰役不僅是鄧禹個人軍事生涯的「洗雪恥辱」之戰，也從戰略上將延岑進一步向南驅趕，減輕了中原地區的軍事壓力。"
