      "readingAid": {
        "translation": "叛亂的漁陽太守彭寵被他手下的家奴殺死，漁陽地區由此平定。",
        "analysis": "【訓詁與名物】：「彭寵」割據幽州、自稱燕王的叛臣。「蒼頭」漢代對奴僕的稱呼，因其以青巾裹頭而得名。「漁陽」彭寵的根據地。「平」平定。\\n\\n【章法與結構】：這是一段戲劇性極強的歷史記錄。前半句是不可一世的叛王死於非命（彭寵為蒼頭殺）；後半句是這個偶然事件帶來的宏大戰略結果（漁陽平）。\\n\\n【思想與義理】：彭寵之死是東漢初年最具戲劇性的事件之一。彭寵擁有精銳的漁陽突騎，自立為燕王，一直是劉秀北方最大的心腹之患。漢軍與其苦戰多年，損兵折將（如鄧隆敗績），始終未能將其消滅。然而，這樣一個強大的軍閥，最終卻因為對下屬刻薄寡恩，被自己的家奴刺殺。彭寵的戲劇性死亡，讓劉秀兵不血刃地收復了整個幽州地區，徹底解除了北方的後顧之憂。這也印證了中國古代政治中「得道多助，失道寡助」、「禍起蕭牆」的傳統政治倫理。"
      }
