        "translation": "三月癸未日，光武帝將叔父廣陽王劉良改封為趙王，劉良這才正式前往封國就任。",
        "analysis": "【訓詁與名物】：「徙」改封。「廣陽王良」即劉秀的叔父劉良，前文建武二年曾封其為廣陽王。「趙王」趙國的諸侯王，治所在邯鄲。「始就國」指被封為王後，第一次離開京城前往自己的封地居住和視事。\\n\\n【章法與結構】：這是一條關於宗室分封與就國的記錄。\\n\\n【思想與義理】：劉良在建武二年就被封為廣陽王，但直到建武五年才「始就國」，這反映了東漢初年宗室分封制度的實際運行情況。在天下未定、戰火紛飛的前幾年，諸侯王往往只是掛個空名，留在皇帝身邊（或參與軍事），無法真正到封地去。此時劉秀將叔父改封到已經完全平定且經濟發達的趙國（邯鄲），並讓他正式就國，說明黃河以北的局勢已經徹底穩定，東漢的諸侯王制度開始進入常態化的實質運行階段。"
