        "analysis": "【訓詁與名物】：「隗囂」隴右軍閥。「子恂」隗囂的兒子隗恂。「入侍」指諸侯或藩屬派子弟到京城皇帝身邊充當侍從，實為人質，以表示臣服和忠誠。\\n\\n【章法與結構】：十一字的外交事件記錄。\\n\\n【思想與義理】：隗囂派兒子入侍，是東漢與西北割據勢力外交博弈中的一次重大事件。此時劉秀已經平定了關東和中原的大部分地區，聲威大震。隗囂感受到了巨大的軍事壓力，為了避免成為漢軍下一個打擊的目標，他選擇了升級自己的「臣服」姿態——從之前的「奉奏」（僅名義上的稱臣），變成了實質性的送交人質（子恂入侍）。這說明劉秀在東方戰場的勝利，已經產生了強大的戰略震懾效應，迫使西方的軍閥不得不做出實質性的妥協。然而，這種基於實力對比的短暫妥協，並不能掩蓋隗囂想要長期割據隴右的真實野心。"
